<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 if (typeof actualValue === 'boolean') {
                     return actualValue;
                 }
                 return String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) {
            return;
        }

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";

        const descriptionMatch = String(fullDisplayString).match(/\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
            descriptionText = descriptionMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim();
        }

        const valueParts = String(fullDisplayString).split('->');
        const currentValueString = valueParts.length > 1 ? valueParts[1].trim() : valueParts[0].trim();

        const valueMatch = currentValueString.match(/^-?\d+(\.\d+)?/);
         if (valueMatch) {
            numericValue = parseFloat(valueMatch[0]);
            valueMainDisplay.innerText = currentValueString;
         } else if (!isNaN(parseFloat(fullDisplayString))) { // Handles if original string was just a number
             numericValue = parseFloat(fullDisplayString);
             valueMainDisplay.innerText = fullDisplayString;
         } else { // Fallback if not readily parsable as number
             if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                 numericValue = rawValueFromCharacterData[0];
                 valueMainDisplay.innerText = String(numericValue);
             } else if (typeof rawValueFromCharacterData === 'number') {
                 numericValue = rawValueFromCharacterData;
                 valueMainDisplay.innerText = String(rawValueFromCharacterData);
             } else {
                 valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
             }
         }


        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if(color) {
                progressBar.style.backgroundColor = color;
            } else {
                progressBar.style.backgroundColor = 'var(--accent-highlight)';
            }
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
             if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }

            const userKey = "{{user}}";
            const stellaKey = "史黛拉";
            const shizukuKey = "黑铁珠雫";
            const toukaKey = "东堂刀华";
            const kuronoKey = "新宫寺黑乃";

            const setText = (id, path) => {
                const el = document.getElementById(id);
                if (el) {
                    let val = SafeGetValue(characterData, path);
                    el.innerText = val;
                }
            };

            if (characterData.hasOwnProperty(userKey)) {
                updateProgressBar('user-stamina-bar', 'user-stamina', 'user-stamina-desc', SafeGetValue(characterData, `${userKey}.体力值`), 0, 100, 'var(--accent-user-stamina)');
                updateProgressBar('user-mana-bar', 'user-mana', 'user-mana-desc', SafeGetValue(characterData, `${userKey}.魔力值`), 0, 100, 'var(--accent-user-mana)');
                setText('user-location', `${userKey}.当前位置`);
                setText('user-thoughts', `${userKey}.内心想法`);
            } else {
                document.getElementById('user-stamina').innerText = 'N/A';
                document.getElementById('user-mana').innerText = 'N/A';
                document.getElementById('user-location').innerText = 'N/A';
                document.getElementById('user-thoughts').innerText = 'N/A';
                const staminaBar = document.getElementById('user-stamina-bar');
                if (staminaBar) staminaBar.style.width = '0%';
                const manaBar = document.getElementById('user-mana-bar');
                if (manaBar) manaBar.style.width = '0%';
            }


            if (characterData.hasOwnProperty(stellaKey)) {
                updateProgressBar('stella-affection-bar', 'stella-affection', 'stella-affection-desc', SafeGetValue(characterData, `${stellaKey}.与{{user}}的好感值`), 0, 100, 'var(--accent-affection)');
                updateProgressBar('stella-tsundere-bar', 'stella-tsundere', 'stella-tsundere-desc', SafeGetValue(characterData, `${stellaKey}.傲娇值`), 0, 100, 'var(--accent-tsundere)');
                updateProgressBar('stella-scheming-bar', 'stella-scheming', 'stella-scheming-desc', SafeGetValue(characterData, `${stellaKey}.腹黑值`), 0, 100, 'var(--accent-scheming)');
                setText('stella-thoughts', `${stellaKey}.内心想法`);
            } else {
                document.getElementById('stella-affection').innerText = 'N/A';
                document.getElementById('stella-tsundere').innerText = 'N/A';
                document.getElementById('stella-scheming').innerText = 'N/A';
                document.getElementById('stella-thoughts').innerText = 'N/A';
            }

            if (characterData.hasOwnProperty(shizukuKey)) {
                updateProgressBar('shizuku-affection-bar', 'shizuku-affection', 'shizuku-affection-desc', SafeGetValue(characterData, `${shizukuKey}.与{{user}}的好感值`), 0, 100, 'var(--accent-affection)');
                setText('shizuku-thoughts', `${shizukuKey}.内心想法`);
            } else {
                document.getElementById('shizuku-affection').innerText = 'N/A';
                document.getElementById('shizuku-thoughts').innerText = 'N/A';
            }

            if (characterData.hasOwnProperty(toukaKey)) {
                updateProgressBar('touka-affection-bar', 'touka-affection', 'touka-affection-desc', SafeGetValue(characterData, `${toukaKey}.与{{user}}的好感值`), 0, 100, 'var(--accent-affection)');
                setText('touka-thoughts', `${toukaKey}.内心想法`);
            } else {
                document.getElementById('touka-affection').innerText = 'N/A';
                document.getElementById('touka-thoughts').innerText = 'N/A';
            }

            if (characterData.hasOwnProperty(kuronoKey)) {
                updateProgressBar('kurono-affection-bar', 'kurono-affection', 'kurono-affection-desc', SafeGetValue(characterData, `${kuronoKey}.与{{user}}的好感值`), 0, 100, 'var(--accent-affection)');
                setText('kurono-thoughts', `${kuronoKey}.内心想法`);
            } else {
                document.getElementById('kurono-affection').innerText = 'N/A';
                document.getElementById('kurono-thoughts').innerText = 'N/A';
            }

            setText('world-date', '日期');
            setText('world-time', '时间');
            setText('world-main-location', '地点');

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('.arrow');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
